// Runs the AI recruiter's evaluation set (brief 36) against a running `score` function and
// writes docs/scoring-eval.md. Zero dependencies (Node 22).
//
//   supabase start
//   supabase functions serve score --env-file <path to .env with GEMINI_API_KEY>
//   node supabase/eval/score/run.mjs [runs per case, default 3]
//
// The cases (cases.json) are generated by the app's own request builder and the engine, see
// apps/mobile/test/features/debrief/score_eval_cases_test.dart. Each run signs up fresh guests
// as needed (the function allows 30 AI scores per player per day). Nothing here reads a key.

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..', '..');
const runs = Number(process.argv[2] ?? 3);
const cases = JSON.parse(readFileSync(join(here, 'cases.json'), 'utf8'));
const status = JSON.parse(
  execFileSync('supabase', ['status', '-o', 'json'], { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] }),
);
const api = status.API_URL;
const anon = status.PUBLISHABLE_KEY ?? status.ANON_KEY;
const QUOTA = 30;
// The owner's Gemini key is on the free tier (per-model requests per minute): pace the calls.
const PACE_MS = Number(process.env.EVAL_PACE_MS ?? 6000);
const DIMENSIONS = ['relevance', 'specificity', 'structure', 'adaptability'];

async function post(url, body, headers) {
  const started = Date.now();
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json', apikey: anon, ...headers },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  let json = null;
  try {
    json = JSON.parse(text);
  } catch {
    // Not JSON: kept as a failure below.
  }
  return { status: res.status, json, ms: Date.now() - started };
}

let jwt = null;
let used = QUOTA;
async function guest() {
  if (used < QUOTA - 1) return jwt;
  const signup = await post(`${api}/auth/v1/signup`, {}, {});
  if (signup.status !== 200) throw new Error(`guest sign-up failed: ${signup.status}`);
  jwt = signup.json.access_token;
  used = 0;
  return jwt;
}

const results = [];
for (const c of cases) {
  for (let i = 0; i < runs; i++) {
    const token = await guest();
    used++;
    await new Promise((resolve) => setTimeout(resolve, PACE_MS));
    const r = await post(`${api}/functions/v1/score`, c.request, { authorization: `Bearer ${token}` });
    const ok = r.status === 200 && r.json?.overall;
    results.push({
      id: c.id,
      kind: c.kind,
      mission: c.mission_id,
      run: i + 1,
      status: r.status,
      ms: r.ms,
      model: ok ? r.json.model : null,
      overall: ok ? r.json.overall.score : null,
      dimensions: ok ? Object.fromEntries(DIMENSIONS.map((d) => [d, r.json.dimensions[d].score])) : null,
      basis: ok ? r.json.overall.basis : null,
    });
    process.stdout.write(`${c.id} #${i + 1}: ${r.status} ${ok ? r.json.overall.score : ''} (${r.ms} ms)\n`);
  }
}
writeFileSync(join(here, 'results.json'), JSON.stringify(results, null, 2) + '\n');

// ---------------------------------------------------------------- the report

const median = (xs) => {
  const s = [...xs].sort((a, b) => a - b);
  return s.length === 0
    ? null
    : s.length % 2
    ? s[(s.length - 1) / 2]
    : Math.round((s[s.length / 2 - 1] + s[s.length / 2]) / 2);
};
const pearson = (xs, ys) => {
  const n = xs.length;
  const mx = xs.reduce((a, b) => a + b, 0) / n;
  const my = ys.reduce((a, b) => a + b, 0) / n;
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < n; i++) {
    sxy += (xs[i] - mx) * (ys[i] - my);
    sxx += (xs[i] - mx) ** 2;
    syy += (ys[i] - my) ** 2;
  }
  return sxy / Math.sqrt(sxx * syy);
};

const scored = results.filter((r) => r.overall !== null);
const byCase = cases.map((c) => {
  const rs = scored.filter((r) => r.id === c.id);
  const overall = rs.map((r) => r.overall);
  const [lo, hi] = c.expected_overall;
  return {
    ...c,
    runs: rs.length,
    overall,
    median: median(overall),
    spread: overall.length ? Math.max(...overall) - Math.min(...overall) : null,
    inBand: overall.filter((o) => o >= lo && o <= hi).length,
  };
});
const answered = byCase.filter((c) => c.median !== null);
const inBand = answered.reduce((a, c) => a + c.inBand, 0);
const spreads = answered.map((c) => c.spread);
const missions = [...new Set(cases.map((c) => c.mission_id))];
const ordered = missions.filter((m) => {
  const get = (k) => answered.find((c) => c.mission_id === m && c.kind === k)?.median;
  const s = get('strong'), w = get('weak'), g = get('guessed');
  return s !== undefined && w !== undefined && g !== undefined && s > w && s > g;
});
const withEngine = answered.filter((c) => c.engine_total !== null);
const r = pearson(withEngine.map((c) => c.engine_total), withEngine.map((c) => c.median));
const mad = withEngine.reduce((a, c) => a + Math.abs(c.engine_total - c.median), 0) / withEngine.length;
const models = scored.reduce((m, x) => ({ ...m, [x.model]: (m[x.model] ?? 0) + 1 }), {});
const latencies = scored.map((x) => x.ms).sort((a, b) => a - b);
const p90 = latencies[Math.floor(latencies.length * 0.9)] ?? null;
const failed = results.length - scored.length;

const pct = (a, b) => (b === 0 ? 'n/a' : `${Math.round((100 * a) / b)} %`);
const lines = [
  '# How well does the AI recruiter score? (evaluation)',
  '',
  `Generated by \`supabase/eval/score/run.mjs\` on ${new Date().toISOString().slice(0, 10)} against the live \`score\``,
  "function with the owner's Gemini key (brief 36). Re-run it after any change to the prompt, the",
  'models or the content; publish the result as it comes, good or bad.',
  '',
  '## The method',
  '',
  `- **${cases.length} answers**: for each of the ${missions.length} Chapter 1 missions, a *strong* answer (the`,
  '  strongest line of every beat, the principle that really explains it, the best reply), a *weak* one',
  '  (the weakest lines, a tempting wrong principle, the worst reply) and a *guessed* one (strong',
  '  lines picked faster than anyone could read them, no reasons). Built from the content by the',
  "  app's own request builder, so the AI sees exactly what a player's answer sends.",
  "- **The expected band** for each kind is the content author's intent: strong 70–100, weak and",
  "  guessed 0–50. **The engine's score** for the same play is the offline reference.",
  `- Each answer is scored **${runs} times** (temperature 0) to measure consistency.`,
  '',
  '## The results',
  '',
  '| Measure | Result | What it tells you |',
  '| --- | --- | --- |',
  `| Verdicts returned | ${scored.length} of ${results.length}${
    failed ? ` (${failed} failed)` : ''
  } | The function and its model chain answered |`,
  `| Within the intended band | ${
    pct(inBand, scored.length)
  } (${inBand} of ${scored.length}) | The AI tells strong from weak the way the author meant |`,
  `| Missions ranked right | ${ordered.length} of ${missions.length} | Strong scored above both weak and guessed |`,
  `| Spread between repeat runs | median ${median(spreads)}, max ${
    Math.max(...spreads)
  } points | Consistency: the same answer gets (nearly) the same score |`,
  `| Agreement with the engine | r = ${r.toFixed(2)}, mean gap ${
    mad.toFixed(1)
  } points | The AI and the offline rules agree on what's good |`,
  `| Latency | median ${
    median(latencies)
  } ms, p90 ${p90} ms | Inside the app's 8 s wait (a later verdict replaces the offline score) |`,
  `| Models that graded | ${
    Object.entries(models).map(([m, n]) => `${m} ×${n}`).join(', ')
  } | The fallback chain at work |`,
  '',
  '## Per answer',
  '',
  '| Answer | Expected | Engine | AI (each run) | AI median | Spread |',
  '| --- | --- | --- | --- | --- | --- |',
  ...byCase.map((c) =>
    `| ${c.id} | ${c.expected_overall.join('–')} | ${c.engine_total ?? '–'} | ${
      c.overall.join(', ') || 'no verdict'
    } | ${c.median ?? '–'} | ${c.spread ?? '–'} |`
  ),
  '',
  '## What the recruiter said (one run each, strong and weak, Mission 1)',
  '',
  ...['strong', 'weak'].map((k) => {
    const x = scored.find((s) => s.id === `m01_the_opportunity_${k}`);
    return `- **${k}** (${x?.overall ?? '–'}): "${x?.basis ?? 'no verdict'}"`;
  }),
  '',
  '## What we changed because of it (2026-11-02)',
  '',
  '- **Every verdict timed out on the first live run.** `gemini-3.8-flash` answered 503 "high demand"',
  '  or took 30 s+ and allows no minimal thinking. The function now tries a chain of faster models',
  '  with minimal thinking, and the app swaps a late verdict in for the offline score (ADR 0006).',
  '- **Guessed answers scored too high** (60 for an answer whose three lines were all guessed, against',
  '  a band of 0–50). The prompt now caps an all-guessed answer at 40 overall and 20 specificity;',
  '  re-scored: 25–40.',
  "- **A weak line with a good-sounding reason scored too high** (65 for Mission 6's blaming answer).",
  '  The prompt now says a good reason never rescues a weak line; re-scored: 45–55.',
  "- **The key is on Gemini's free tier**: per-model rate limits (429) cause most of the missing",
  '  verdicts here. The app falls back to the offline score when that happens; production needs',
  '  billing on the key.',
  '',
  '## Honest limits',
  '',
  '- The bands are our own intent, not an outside benchmark: this shows the AI agrees with the',
  '  rubric we wrote, not that the rubric matches every recruiter.',
  '- 21 answers is small; it catches a broken prompt or a model swap, not subtle bias.',
  "- Temperature 0 narrows the spread but doesn't remove it; progress over time (the baseline, the",
  '  report) stays on the engine for that reason (ADR 0006).',
  '',
];
writeFileSync(join(root, 'docs', 'scoring-eval.md'), lines.join('\n'));
console.log(
  `\nwrote docs/scoring-eval.md: ${
    pct(inBand, scored.length)
  } in band, ${ordered.length}/${missions.length} ranked, r=${r.toFixed(2)}`,
);
